children.dataScript:
(function() {
  var items = [];
  var count = DataManager.maxSavefiles();
  for (var i = 1; i <= count; i++) {
    var info = DataManager.loadSavefileInfo(i);
    var valid = DataManager.isThisGameFile(i);
    var chars = [];
    if (valid && info && info.characters) {
      for (var j = 0; j < Math.min(info.characters.length, 4); j++) {
        var c = info.characters[j];
        chars.push([c[0], c[1], 220 + j * 48, 100]);
      }
    }
    items.push({
      name: TextManager.file + ' ' + i,
      symbol: i,
      enabled: true,
      subText: (info && info.title) ? info.title : '',
      rightText: (info && info.playtime) ? info.playtime : '',
      characters: chars
    });
  }
  return items;
})()
